def evaluate_submissions(
    submissions: Iterable[Candidate],
    validation_score: Callable[[Candidate], float],
    test_score: Callable[[Candidate], float],
) -> list[dict[str, int | float]]:
    records = []
    for submission_id, candidate in enumerate(submissions):
        records.append({
            "submission_id": submission_id,
            "validation_score": validation_score(candidate),
            "test_score": test_score(candidate),
        })
    return records
